#!/usr/bin/env node
// ============================================================
// sync-nvidia-manifest.js
// Copies the canonical NVIDIA skills manifest (generated by
// build-nvidia-skills-manifest.js in this folder) into the
// shaddai-mcp repo so BOTH MCP servers expose an identical catalog.
//
// Usage:
//   node sync-nvidia-manifest.js [targetRepoPath]
//
// Target resolution, in order:
//   1. argv[2]
//   2. SHADDAI_MCP_REPO environment variable
//   3. ../shaddai-mcp-repo next to this package (the usual layout)
//   4. C:/Users/Brittany/shaddai-mcp-repo
//
// The repo copy is a bare JSON array (the shape the repo's rag-index
// loader expects). Machine-local fields (installed, path) are dropped
// because they describe this machine, not the catalog.
// ============================================================
const fs = require('fs');
const path = require('path');

const SRC = path.join(__dirname, 'nvidia-skills.json');

function resolveTargetRepo() {
  const candidates = [
    process.argv[2],
    process.env.SHADDAI_MCP_REPO,
    path.resolve(__dirname, '..', 'shaddai-mcp-repo'),
    'C:/Users/Brittany/shaddai-mcp-repo',
  ].filter(Boolean);
  for (const c of candidates) {
    if (fs.existsSync(path.join(c, 'skills'))) return c;
  }
  return null;
}

const TARGET_REPO = resolveTargetRepo();
if (!TARGET_REPO) {
  console.error('Could not find the shaddai-mcp repo to sync into.');
  console.error('Pass the path as an argument, or set SHADDAI_MCP_REPO:');
  console.error('  node sync-nvidia-manifest.js C:/path/to/shaddai-mcp-repo');
  process.exit(1);
}
const DST = path.join(TARGET_REPO, 'skills', 'nvidia-skills.json');

const src = JSON.parse(fs.readFileSync(SRC, 'utf8'));
const skills = Array.isArray(src) ? src : (src.skills || []);
if (!skills.length) {
  console.error('source manifest has no skills');
  process.exit(1);
}

const out = skills.map((s) => {
  const e = {
    id: s.id,
    name: s.name,
    version: s.version || '',
    license: s.license || '',
    description: s.description,
    category: s.category,
    source: s.source || 'NVIDIA/skills',
    requiresGpu: !!s.requiresGpu,
  };
  if (s.requiresGpu) e.gpuReason = s.gpuReason || 'Requires an NVIDIA GPU to execute its model steps.';
  e.sapRelevance = s.sapRelevance;
  return e;
});

fs.mkdirSync(path.dirname(DST), { recursive: true });
fs.writeFileSync(DST, JSON.stringify(out, null, 2) + '\n', 'utf8');

const gpu = out.filter((s) => s.requiresGpu).length;
console.log('synced -> ' + DST);
console.log('  skills: ' + out.length + ' | requiresGpu true: ' + gpu + ' | false: ' + (out.length - gpu));
const bad = JSON.stringify(out).match(/[^\x00-\x7F]/g);
console.log('  non-ascii codepoints: ' + (bad ? bad.length : 0));
const ids = out.map((s) => s.id);
console.log('  unique ids: ' + new Set(ids).size + ' | id set matches source: ' +
  (JSON.stringify(ids.slice().sort()) === JSON.stringify(skills.map((s) => s.id).slice().sort())));
